const bikes=[
 {name:'Classic 350',type:'CLASSIC',tag:'Unhurried, unmistakable',route:'The Old Quarter',terrain:'City streets',tip:'“The city wakes up one corner at a time.”',scene:'city',color:'#b95d39',speed:76},
 {name:'Bullet 350',type:'CLASSIC',tag:'A legend, still moving',route:'The Village Loop',terrain:'Village lanes',tip:'“Dust on the road. Time on your side.”',scene:'village',color:'#315849',speed:72},
 {name:'Hunter 350',type:'ROADSTER',tag:'Made for the detour',route:'The Backstreet Run',terrain:'City streets',tip:'“Take the turn you almost missed.”',scene:'city',color:'#e4ae39',speed:88},
 {name:'Continental GT 650',type:'CAFE RACER',tag:'Lean into the long way',route:'The Night Circuit',terrain:'City traffic',tip:'“A little speed. A lot of city.”',scene:'night',color:'#ba3c31',speed:105},
 {name:'Interceptor 650',type:'ROADSTER',tag:'Two cylinders. One horizon.',route:'The Coastal Bend',terrain:'Open highway',tip:'“Keep the horizon where you can see it.”',scene:'coast',color:'#e7a64d',speed:102},
 {name:'Himalayan 450',type:'ADVENTURE',tag:'Find the high country',route:'The High Pass',terrain:'Mountain trail',tip:'“The best view asks you to climb.”',scene:'mountain',color:'#4d736a',speed:95},
 {name:'Scram 440',type:'SCRAMBLER',tag:'City edge to wild edge',route:'The Scramble Track',terrain:'Hilly backroad',tip:'“Leave the neat lines behind.”',scene:'hill',color:'#d47c3b',speed:86},
 {name:'Guerrilla 450',type:'ROADSTER',tag:'A little wild, everywhere',route:'The Hill Run',terrain:'Hilly backroad',tip:'“Every bend has another idea.”',scene:'hill',color:'#657b4b',speed:98},
 {name:'Super Meteor 650',type:'CRUISER',tag:'Settle into the miles',route:'The Sunset Highway',terrain:'Open highway',tip:'“Let the miles come to you.”',scene:'coast',color:'#586b8c',speed:94},
 {name:'Shotgun 650',type:'CUSTOM',tag:'Built to break the routine',route:'The Midnight Mile',terrain:'City streets',tip:'“The night belongs to the curious.”',scene:'night',color:'#8a526c',speed:100}
];
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
let W=0,H=0,dpr=1,selected=0,running=false,paused=false,gameOver=false,playerLane=1,distance=0,marks=0,world=0,spawnTimer=0,objects=[],last=0,shake=0;
const grid=document.getElementById('bikeGrid');
bikes.forEach((b,i)=>{const btn=document.createElement('button');btn.className='bike-card'+(i===0?' selected':'');btn.innerHTML=`<span class="bike-type">${b.type}</span><span class="bike-name">${b.name}</span><span class="bike-tag">${b.tag}</span>`;btn.addEventListener('click',()=>selectBike(i));grid.appendChild(btn)});
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
new ResizeObserver(resize).observe(canvas);resize();
function selectBike(i){if(running)return;selected=i;document.querySelectorAll('.bike-card').forEach((el,j)=>el.classList.toggle('selected',j===i));const b=bikes[i];document.getElementById('rideName').textContent=b.name;document.getElementById('routeName').textContent=b.route;document.getElementById('terrainName').textContent=b.terrain;document.getElementById('routeTip').textContent=b.tip;document.getElementById('stateKicker').textContent=b.type+' · '+b.terrain;draw()}
function startRide(){running=true;paused=false;gameOver=false;distance=0;marks=0;world=0;objects=[];spawnTimer=.45;playerLane=1;shake=0;document.getElementById('gameState').style.display='none';last=performance.now();requestAnimationFrame(loop)}
function endRide(){running=false;gameOver=true;document.getElementById('stateKicker').textContent='Ride complete · '+Math.floor(distance)+' m';document.getElementById('stateTitle').innerHTML='The road<br>keeps going.';document.getElementById('stateText').textContent=`You collected ${marks} route mark${marks===1?'':'s'} on ${bikes[selected].name}. Catch your breath, then take another road.`;document.getElementById('startBtn').textContent='Ride again  →';document.getElementById('gameState').style.display='grid'}
document.getElementById('startBtn').addEventListener('click',startRide);
function move(dir){if(!running)return;playerLane=Math.max(0,Math.min(2,playerLane+dir))}
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','a','A','d','D'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')move(-1);if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')move(1);if(e.key===' '&&running){paused=!paused;if(!paused){last=performance.now();requestAnimationFrame(loop)}}});
function bindTouch(id,dir){const el=document.getElementById(id);el.addEventListener('pointerdown',e=>{e.preventDefault();move(dir)})}bindTouch('leftBtn',-1);bindTouch('rightBtn',1);
function poly(points,fill){ctx.fillStyle=fill;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fill()}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(x,y,w,h)}
function circle(x,y,r,c){ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function drawBackground(){const b=bikes[selected],s=b.scene, horizon=H*.49, t=world;
 let sky1='#d8d1b8',sky2='#e6dec7',ground='#68775e';if(s==='city'){sky1='#afc4c3';sky2='#e2d4b8';ground='#7c866e'}if(s==='village'){sky1='#9fc5c3';sky2='#ead2a6';ground='#6d8250'}if(s==='mountain'){sky1='#9ab9be';sky2='#e9cfaa';ground='#526a4e'}if(s==='hill'){sky1='#9dc1bd';sky2='#e7d4ae';ground='#59744c'}if(s==='coast'){sky1='#9fc9d0';sky2='#efd5aa';ground='#718257'}if(s==='night'){sky1='#152b3c';sky2='#344954';ground='#26382e'}
 const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,sky1);g.addColorStop(.7,sky2);g.addColorStop(1,ground);rect(0,0,W,H,g);
 const sunX=W*.78,sunY=H*.22;circle(sunX,sunY,H*(s==='night'?.032:.055),s==='night'?'#f5dca0':'#f6dfad');
 if(s==='mountain'||s==='hill'){poly([[0,horizon+12],[W*.11,H*.28],[W*.2,H*.43],[W*.35,H*.2],[W*.49,H*.48],[W*.66,H*.25],[W*.78,H*.44],[W*.9,H*.23],[W,horizon+8],[W,H*.64],[0,H*.64]],s==='mountain'?'#6c8c8a':'#81956d');poly([[0,H*.52],[W*.19,H*.4],[W*.34,H*.55],[W*.55,H*.34],[W*.73,H*.54],[W*.9,H*.38],[W,H*.49],[W,H*.67],[0,H*.67]],s==='mountain'?'#aab7a3':'#9aab79');if(s==='mountain'){poly([[W*.35,H*.2],[W*.29,H*.35],[W*.35,H*.31],[W*.4,H*.37],[W*.44,H*.42]],'#eee6d4');poly([[W*.9,H*.23],[W*.85,H*.38],[W*.9,H*.34],[W*.94,H*.4]],'#eee6d4')}}
 else if(s==='coast'){rect(0,H*.4,W,H*.16,'#82b5b4');for(let i=0;i<5;i++){const y=H*.42+i*H*.026;ctx.strokeStyle='#d9e2d0aa';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,y+Math.sin(t*2+i)*3);ctx.quadraticCurveTo(W*.5,y-3,W,y+Math.cos(t+i)*4);ctx.stroke()}poly([[0,H*.53],[W*.24,H*.49],[W*.5,H*.55],[W*.75,H*.51],[W,H*.54],[W,H*.68],[0,H*.68]],'#819467')}
 else if(s==='village'){poly([[0,H*.53],[W*.1,H*.4],[W*.21,H*.5],[W*.36,H*.39],[W*.51,H*.52],[W*.71,H*.37],[W*.88,H*.51],[W,H*.42],[W,H*.68],[0,H*.68]],'#84915e');for(let i=0;i<7;i++){let x=i*W/6+20,y=H*(.44+(i%3)*.035);drawTree(x,y,1+(i%2)*.2,'#536c45')}}
 else if(s==='city'||s==='night'){for(let i=0;i<11;i++){let x=i*W/10+((i%2)*8),bw=W*.065,bh=H*(.13+(i*17%11)/100);let y=horizon-bh+4;rect(x,y,bw,bh,s==='night'?'#263b47':'#9b9c88');rect(x+3,y+5,bw-6,2,s==='night'?'#f5d68a':'#d9c9a7');for(let wy=y+12;wy<horizon;wy+=12)for(let wx=x+6;wx<x+bw-4;wx+=10)rect(wx,wy,3,4,s==='night'?'#f4cb7a':'#ddcea8')}if(s==='city'){for(let i=0;i<4;i++)drawTree(W*(.06+i*.29),H*.49,1,'#526c4e')}}
 drawRoad();
}
function drawTree(x,y,scale,color){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);rect(-2,-18,4,19,'#594837');circle(0,-24,11,color);circle(-7,-20,7,color);circle(7,-20,7,color);ctx.restore()}
function drawRoad(){const vanX=W*.5,hy=H*.5,bottom=H+8,roadTop=W*.11,roadBottom=W*.86,offset=(world*150)%80;poly([[vanX-roadTop/2,hy],[vanX+roadTop/2,hy],[vanX+roadBottom/2,bottom],[vanX-roadBottom/2,bottom]],'#494b43');poly([[vanX-roadTop*.65,hy],[vanX-roadTop/2,hy],[vanX-roadBottom/2,bottom],[vanX-roadBottom*.67,bottom]],'#b2a987');poly([[vanX+roadTop/2,hy],[vanX+roadTop*.65,hy],[vanX+roadBottom*.67,bottom],[vanX+roadBottom/2,bottom]],'#b2a987');
 for(let i=0;i<16;i++){let p=((i*43+offset)%690)/690,y=hy+p*p*(H-hy);let scale=.09+p*.9;let dash=H*.085*scale;for(let lane=1;lane<=2;lane++){let x=vanX+(lane-1.5)*(roadTop+(roadBottom-roadTop)*p)/3;rect(x-1.3*scale,y,2.6*scale,dash,'#e3d9b8')} }
 // edge dust and subtle asphalt grain
 ctx.strokeStyle='#d8c79655';ctx.lineWidth=1;for(let i=0;i<24;i++){let p=((i*37+offset*1.1)%600)/600,y=hy+p*p*(H-hy),x=vanX+(i%2?1:-1)*(roadTop+(roadBottom-roadTop)*p)/2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+(i%2?1:-1)*10*p,y+3*p);ctx.stroke()}
}

function spawn(){let lane=Math.floor(Math.random()*3),token=Math.random()<.36;objects.push({lane,p:0,type:token?'token':'car',variant:Math.floor(Math.random()*3)});if(Math.random()<.2)objects.push({lane:(lane+1+Math.floor(Math.random()*2))%3,p:-.12,type:Math.random()<.42?'token':'car',variant:1})}
function laneX(lane,p){return W*.5+(lane-1)*(W*(.11+(.86-.11)*p)/3)}
function drawCar(x,y,scale,variant){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);const colors=['#ddc9a2','#597b70','#c26746'];const c=colors[variant];ctx.shadowColor='#18201966';ctx.shadowBlur=6;ctx.shadowOffsetY=3;ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(-14,-17);ctx.quadraticCurveTo(-13,-23,-7,-24);ctx.lineTo(7,-24);ctx.quadraticCurveTo(13,-22,14,-17);ctx.lineTo(17,12);ctx.quadraticCurveTo(17,18,11,19);ctx.lineTo(-11,19);ctx.quadraticCurveTo(-17,18,-17,12);ctx.closePath();ctx.fill();ctx.shadowColor='transparent';ctx.fillStyle='#283c3d';ctx.beginPath();ctx.moveTo(-10,-15);ctx.lineTo(-7,-21);ctx.lineTo(7,-21);ctx.lineTo(10,-15);ctx.closePath();ctx.fill();ctx.fillStyle='#e7d5a5';ctx.fillRect(-12,-16,5,2);ctx.fillRect(7,-16,5,2);ctx.fillStyle='#282723';ctx.fillRect(-16,9,4,8);ctx.fillRect(12,9,4,8);ctx.fillStyle='#e35c39';ctx.fillRect(-8,14,16,3);ctx.restore()}
function drawToken(x,y,scale){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.shadowColor='#f9c36b';ctx.shadowBlur=13;circle(0,0,9,'#eaa44f');ctx.shadowBlur=0;circle(0,0,5,'#533a26');circle(0,0,2,'#f1cb83');ctx.restore()}
function drawBike(x,y,scale){const c=bikes[selected].color;ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.shadowColor='#111b1888';ctx.shadowBlur=13;ctx.shadowOffsetY=8;
 // wheels
 ctx.lineWidth=5;ctx.strokeStyle='#202522';ctx.beginPath();ctx.arc(-18,20,12,0,Math.PI*2);ctx.arc(18,20,12,0,Math.PI*2);ctx.stroke();ctx.shadowColor='transparent';ctx.lineWidth=1.5;ctx.strokeStyle='#b8b8a8';ctx.beginPath();ctx.arc(-18,20,8,0,Math.PI*2);ctx.arc(18,20,8,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(-18,12);ctx.lineTo(-18,28);ctx.moveTo(-26,20);ctx.lineTo(-10,20);ctx.moveTo(18,12);ctx.lineTo(18,28);ctx.moveTo(10,20);ctx.lineTo(26,20);ctx.stroke();
 // frame / fork
 ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=4;ctx.strokeStyle='#313b35';ctx.beginPath();ctx.moveTo(-18,18);ctx.lineTo(-5,0);ctx.lineTo(6,19);ctx.lineTo(18,18);ctx.moveTo(-5,0);ctx.lineTo(14,-4);ctx.lineTo(18,18);ctx.moveTo(6,19);ctx.lineTo(-2,19);ctx.stroke();ctx.strokeStyle='#d5bd85';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(17,-4);ctx.lineTo(22,16);ctx.moveTo(13,-7);ctx.lineTo(23,-7);ctx.stroke();
 // tank and saddle
 ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(-9,-7);ctx.quadraticCurveTo(-8,-15,2,-13);ctx.lineTo(12,-8);ctx.quadraticCurveTo(13,-5,7,-3);ctx.lineTo(-5,-2);ctx.closePath();ctx.fill();ctx.fillStyle='#282a26';ctx.beginPath();ctx.moveTo(-8,-11);ctx.lineTo(-15,-12);ctx.quadraticCurveTo(-19,-11,-17,-8);ctx.lineTo(-7,-7);ctx.closePath();ctx.fill();ctx.fillStyle='#d9c99d';ctx.beginPath();ctx.ellipse(2,-8,3,1.2,0,0,Math.PI*2);ctx.fill();
 // rider silhouette
 ctx.fillStyle='#242b27';ctx.beginPath();ctx.moveTo(-7,-14);ctx.lineTo(-2,-24);ctx.quadraticCurveTo(2,-28,6,-23);ctx.lineTo(11,-12);ctx.lineTo(5,-9);ctx.lineTo(0,-17);ctx.lineTo(-2,-10);ctx.closePath();ctx.fill();ctx.fillStyle='#252923';ctx.beginPath();ctx.arc(1,-29,5.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d3b88a';ctx.beginPath();ctx.arc(2,-30,4.6,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#dfb76d';ctx.beginPath();ctx.arc(21,-2,3.2,0,Math.PI*2);ctx.fill();ctx.restore()}
function render(){if(!W||!H)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);drawBackground();const hy=H*.5;objects.slice().sort((a,b)=>a.p-b.p).forEach(o=>{if(o.p<0)return;const p=Math.min(1,o.p),y=hy+p*p*(H-hy),scale=.22+p*.92,x=laneX(o.lane,p);if(o.type==='token')drawToken(x,y,scale);else drawCar(x,y,scale,o.variant)});const p=.92;drawBike(laneX(playerLane,p),H*.84,Math.min(W/560,1.08)*.92);if(!running&&!gameOver){ctx.fillStyle='#f7e7c4';ctx.font=`${Math.max(9,W*.013)}px system-ui`;ctx.textAlign='center';ctx.fillText('A GOOD ROAD NEVER ASKS YOU TO HURRY',W/2,H*.92)}}
function loop(now){if(!running||paused)return;const dt=Math.min((now-last)/1000,.04);last=now;const b=bikes[selected],pace=1+Math.min(distance/2200,.65);world+=dt*pace;distance+=dt*pace*10;spawnTimer-=dt;if(spawnTimer<=0){spawn();spawnTimer=Math.max(.56,1.05-distance/8000)+(Math.random()*.38)}
 for(let i=objects.length-1;i>=0;i--){const o=objects[i];o.p+=dt*(.24+pace*.055);if(o.p>.91&&o.p<.97&&o.lane===playerLane){if(o.type==='token'){marks++;objects.splice(i,1);continue}else{shake=.28;endRide();break}}if(o.p>1.08)objects.splice(i,1)}
 if(!running)return;document.getElementById('distance').textContent=Math.floor(distance);document.getElementById('marks').textContent=marks;document.getElementById('speed').textContent=Math.floor(b.speed*pace);render();requestAnimationFrame(loop)}
function draw(){render()}draw();
</script>
</body>
</html>

