import * as THREE from '/public/vendor/three/build/three.module.js';
import { GLTFLoader } from '/public/vendor/three/examples/jsm/loaders/GLTFLoader.js';

const bikes=[
 {name:'Classic 350',type:'CLASSIC',tag:'Unhurried, unmistakable',route:'The Country Lane',terrain:'Village lanes',tip:'“Dust on the road. Time on your side.”',scene:'village',color:'#b95d39',speed:76,model:'classic',rpm:1.04,pulse:1.8},
 {name:'Bullet 350',type:'CLASSIC',tag:'A legend, still moving',route:'The Village Loop',terrain:'Village lanes',tip:'“Dust on the road. Time on your side.”',scene:'village',color:'#315849',speed:72,model:'classic',rpm:.96,pulse:1.7},
 {name:'Hunter 350',type:'ROADSTER',tag:'Made for the detour',route:'The Backstreet Run',terrain:'City streets',tip:'“Take the turn you almost missed.”',scene:'city',color:'#e4ae39',speed:88,model:'roadster',rpm:1.28,pulse:2.1},
 {name:'Continental GT 650',type:'CAFE RACER',tag:'Lean into the long way',route:'The Night Circuit',terrain:'City traffic',tip:'“A little speed. A lot of city.”',scene:'night',color:'#ba3c31',speed:105,model:'roadster',rpm:1.62,pulse:2.4},
 {name:'Interceptor 650',type:'ROADSTER',tag:'Two cylinders. One horizon.',route:'The Coastal Bend',terrain:'Open highway',tip:'“Keep the horizon where you can see it.”',scene:'coast',color:'#e7a64d',speed:102,model:'classic',rpm:1.48,pulse:2.25},
 {name:'Himalayan 450',type:'ADVENTURE',tag:'Find the high country',route:'The High Pass',terrain:'Mountain trail',tip:'“The best view asks you to climb.”',scene:'mountain',color:'#4d736a',speed:95,model:'adventure',rpm:1.4,pulse:2.15},
 {name:'Scram 440',type:'SCRAMBLER',tag:'City edge to wild edge',route:'The Scramble Track',terrain:'Hilly backroad',tip:'“Leave the neat lines behind.”',scene:'hill',color:'#d47c3b',speed:86,model:'adventure',rpm:1.3,pulse:2.0},
 {name:'Guerrilla 450',type:'ROADSTER',tag:'A little wild, everywhere',route:'The Hill Run',terrain:'Hilly backroad',tip:'“Every bend has another idea.”',scene:'hill',color:'#657b4b',speed:98,model:'roadster',rpm:1.52,pulse:2.2},
 {name:'Super Meteor 650',type:'CRUISER',tag:'Settle into the miles',route:'The Sunset Highway',terrain:'Open highway',tip:'“Let the miles come to you.”',scene:'coast',color:'#586b8c',speed:94,model:'classic',rpm:1.24,pulse:1.95},
 {name:'Shotgun 650',type:'CUSTOM',tag:'Built to break the routine',route:'The Midnight Mile',terrain:'City streets',tip:'“The night belongs to the curious.”',scene:'night',color:'#8a526c',speed:100,model:'roadster',rpm:1.5,pulse:2.25}
];
const canvas=document.getElementById('game'),grid=document.getElementById('bikeGrid');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1.7));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(54,1,.1,700);camera.position.set(0,4.1,9);
scene.add(new THREE.HemisphereLight(0xe4f0ff,0x64513c,2.1));const sun=new THREE.DirectionalLight(0xffedce,3.1);sun.position.set(-5,12,8);scene.add(sun);const fill=new THREE.DirectionalLight(0xa6c9d8,1.3);fill.position.set(8,5,-12);scene.add(fill);
let selected=0,running=false,paused=false,gameOver=false,playerLane=0,lanePosition=0,distance=0,marks=0,pace=1,spawnTimer=1,last=0,clock=0,objects=[],scenery=[],currentModel=null,modelVersion=0,audio=null,roadMarks=[];
const roadGroup=new THREE.Group(),worldGroup=new THREE.Group(),bikePivot=new THREE.Group();scene.add(roadGroup,worldGroup,bikePivot);bikePivot.position.set(0,0,2.1);
const mat=(color,roughness=.85,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
function mesh(geometry,material,x,y,z,parent=worldGroup){const o=new THREE.Mesh(geometry,material);o.position.set(x,y,z);parent.add(o);return o}
const groundMaterial=mat('#758364');const ground=new THREE.Mesh(new THREE.PlaneGeometry(900,900),groundMaterial);ground.rotation.x=-Math.PI/2;ground.position.set(0,-.08,-350);scene.add(ground);
const asphalt=mat('#343a3b',.96),edgeMat=mat('#c5b88f'),lineMat=mat('#f1dfaa');
function disposeGroup(group){while(group.children.length){const child=group.children[group.children.length-1];group.remove(child);child.traverse?.(node=>{if(node.geometry)node.geometry.dispose();if(Array.isArray(node.material))node.material.forEach(m=>m.dispose());else if(node.material)node.material?.dispose()})}}
function makeRoad(){disposeGroup(roadGroup);const s=bikes[selected].scene,width=s==='mountain'||s==='hill'?8.5:11.5;const road=mesh(new THREE.PlaneGeometry(width,520),asphalt,0,.005,-220,roadGroup);road.rotation.x=-Math.PI/2;
 for(const x of [-width/2-.22,width/2+.22])mesh(new THREE.BoxGeometry(.2,.025,520),edgeMat,x,.035,-220,roadGroup);
 roadMarks=[];for(let z=8;z>-510;z-=15)for(let lane=-1;lane<=1;lane+=2){const mark=mesh(new THREE.BoxGeometry(.12,.025,5),lineMat,lane*width/6,.04,z,roadGroup);roadMarks.push(mark)}
 const shoulder=mat(s==='mountain'||s==='hill'?'#66594a':s==='coast'?'#b7a16e':s==='city'||s==='night'?'#55554d':'#85775c');for(const side of [-1,1]){const m=mesh(new THREE.PlaneGeometry(45,540),shoulder,side*(width/2+22.5),-.025,-220,roadGroup);m.rotation.x=-Math.PI/2}}
function addTree(x,z,scale=1){const group=new THREE.Group();group.position.set(x,0,z);worldGroup.add(group);mesh(new THREE.CylinderGeometry(.13*scale,.22*scale,2.3*scale,7),mat('#5a4331'),0,1.1*scale,0,group);const colors=['#4f6b46','#60794a','#788453'];for(let i=0;i<3;i++){const crown=mesh(new THREE.IcosahedronGeometry((1.05-i*.1)*scale,1),mat(colors[i]),0,(2.25+i*.42)*scale,0,group);crown.scale.set(1,1.1,.9)}scenery.push({group,z,speed:1})}
function addBuilding(x,z,night=false){const group=new THREE.Group();group.position.set(x,0,z);worldGroup.add(group);const h=3+Math.random()*7,w=2.8+Math.random()*2;mesh(new THREE.BoxGeometry(w,h,3.5),mat(night?'#293b48':['#b39d7d','#9e9a80','#c2ad8a'][Math.floor(Math.random()*3)]),0,h/2,0,group);for(let y=1.3;y<h-.5;y+=1.35)for(let xx=-w*.3;xx<w*.4;xx+=1.25)mesh(new THREE.PlaneGeometry(.42,.55),mat(night?'#e7bd72':'#d7c79e'),xx,y,1.76,group);scenery.push({group,z,speed:1})}
function addRock(x,z,s=1){const group=new THREE.Group();group.position.set(x,0,z);worldGroup.add(group);mesh(new THREE.DodecahedronGeometry(1.3*s,0),mat(['#777a70','#8a806e','#68786c'][Math.floor(Math.random()*3)]),0,.45*s,0,group).scale.set(1.6,.65,1);scenery.push({group,z,speed:1})}

