function addRock(x,z,s=1){const group=new THREE.Group();group.position.set(x,0,z);worldGroup.add(group);mesh(new THREE.DodecahedronGeometry(1.3*s,0),mat(['#777a70','#8a806e','#68786c'][Math.floor(Math.random()*3)]),0,.45*s,0,group).scale.set(1.6,.65,1);scenery.push({group,z,speed:1})}
function makeBackdrop(){const s=bikes[selected].scene,hillside=s==='mountain'||s==='hill',city=s==='city'||s==='night';
 if(hillside)for(let i=0;i<12;i++){const side=i%2?1:-1,x=side*(11+Math.random()*36),z=-35-Math.random()*210;const m=mesh(new THREE.ConeGeometry(9+Math.random()*15,18+Math.random()*30,5),mat(s==='mountain'?'#758b83':'#82906a'),x,8+Math.random()*5,z);m.rotation.z=(Math.random()-.5)*.24;scenery.push({group:m,z,speed:.42});if(s==='mountain'&&i%3===0){const snow=mesh(new THREE.ConeGeometry(4,7,5),mat('#deded2'),x,18,z);snow.position.y=m.position.y+7;scenery.push({group:snow,z,speed:.42})}}
 if(s==='coast'){const water=mesh(new THREE.PlaneGeometry(130,300),mat('#5e9b9d'),-79,-.03,-170);water.rotation.x=-Math.PI/2;for(let i=0;i<10;i++){const hill=mesh(new THREE.SphereGeometry(1,10,7),mat('#758a59'),(i%2?1:-1)*(18+Math.random()*14),2+Math.random()*3,-25-i*20);hill.scale.set(14,3,20);scenery.push({group:hill,z:hill.position.z,speed:.4})}}
 if(city)for(const side of [-1,1])for(let i=0;i<20;i++)addBuilding(side*(12+Math.random()*15),-15-i*19,s==='night');
 else if(!hillside)for(const side of [-1,1])for(let i=0;i<42;i++){const x=side*(10+Math.random()*24),z=-12-i*12;if(s==='village'&&i%5===1)addBuilding(x,z,false);else addTree(x,z,.65+Math.random()*.85)}
 if(hillside)for(const side of [-1,1])for(let i=0;i<28;i++){const z=-10-i*13;if(i%3===0)addRock(side*(7+Math.random()*5),z,.5+Math.random()*.7);else addTree(side*(9+Math.random()*11),z,.55+Math.random()*.75)}}
function buildWorld(){disposeGroup(worldGroup);scenery=[];objects=[];const s=bikes[selected].scene;scene.background=new THREE.Color(s==='night'?'#152b3c':s==='coast'?'#a7cdd0':s==='mountain'?'#9eb9c0':'#b8c9bc');scene.fog=new THREE.Fog(scene.background,75,310);groundMaterial.color.set(s==='village'?'#718052':s==='coast'?'#829060':s==='night'?'#24382f':'#74805d');makeRoad();makeBackdrop()}
function makeCar(variant){const g=new THREE.Group(),paint=mat(['#d5c6a5','#587d75','#bd694a','#74859a'][variant%4],.34,.22),glass=new THREE.MeshPhysicalMaterial({color:'#263d43',roughness:.18,metalness:.25,clearcoat:.6});mesh(new THREE.BoxGeometry(1.7,.58,3),paint,0,.72,0,g);mesh(new THREE.BoxGeometry(1.35,.55,1.42),glass,0,1.18,-.12,g);mesh(new THREE.BoxGeometry(1.48,.08,.08),mat('#f3d9a1',.3),0,.68,-1.52,g);mesh(new THREE.BoxGeometry(1.45,.09,.08),mat('#bd3e2e',.4),0,.68,1.52,g);for(const x of [-.78,.78])for(const z of [-.95,.95]){const wheel=mesh(new THREE.CylinderGeometry(.31,.31,.16,12),mat('#1d2222'),x,.36,z,g);wheel.rotation.z=Math.PI/2}return g}
const tokenGeometry=new THREE.TorusGeometry(.45,.095,10,22),tokenMaterial=new THREE.MeshStandardMaterial({color:'#e4a957',metalness:.78,roughness:.24,emissive:'#6d3510',emissiveIntensity:.42});
function spawn(){const b=bikes[selected],lane=Math.floor(Math.random()*3)-1,isToken=Math.random()<.36;let group;if(isToken){group=new THREE.Group();const ring=mesh(tokenGeometry,tokenMaterial,0,1.3,0,group);ring.rotation.y=Math.PI/2;mesh(new THREE.SphereGeometry(.12,12,8),mat('#f5d496',.3,.5),0,1.3,0,group)}else group=makeCar(Math.floor(Math.random()*4));group.position.set(lane*2.55,0,-170);worldGroup.add(group);objects.push({group,lane,type:isToken?'token':'car',z:-170});if(Math.random()<(b.type==='CAFE RACER'?.34:.17)){const next=lane+(Math.random()<.5?-1:1),second=makeCar(1+Math.floor(Math.random()*3));second.position.set(next*2.55,0,-192);worldGroup.add(second);objects.push({group:second,lane:next,type:'car',z:-192})}}

