function stopAudio(){if(audio)audio.out.gain.setTargetAtTime(0,audio.ctx.currentTime,.35)}
function setOverlay(show,title,kicker,text,button){const panel=document.getElementById('gameState');panel.style.display=show?'grid':'none';if(title!==undefined)document.getElementById('stateTitle').innerHTML=title;if(kicker!==undefined)document.getElementById('stateKicker').textContent=kicker;if(text!==undefined)document.getElementById('stateText').textContent=text;if(button!==undefined)document.getElementById('startBtn').textContent=button}
function updateHud(){document.getElementById('distance').textContent=Math.floor(distance).toLocaleString();document.getElementById('marks').textContent=marks;document.getElementById('speed').textContent=running&&!paused?Math.round(bikes[selected].speed*pace):0}
function startRide(){if(running&&!gameOver){paused=false;setOverlay(false);return}distance=0;marks=0;pace=1;spawnTimer=.75;playerLane=0;lanePosition=0;gameOver=false;running=true;paused=false;objects.forEach(o=>worldGroup.remove(o.group));objects=[];buildAudio();setOverlay(false);updateHud()}
function pauseRide(){if(!running||gameOver)return;paused=!paused;setOverlay(paused,'Take a breather','Ride paused','Your route is waiting. Resume when you’re ready.', 'Resume ride  →');if(paused)stopAudio();else buildAudio()}
function endRide(){running=false;gameOver=true;stopAudio();setOverlay(true,'Ride on.\nTry again?','Ride complete',`You covered ${Math.floor(distance)} m and collected ${marks} route marks.`, 'Ride again  →');updateHud()}
function changeLane(direction){if(!running||paused||gameOver)return;playerLane=THREE.MathUtils.clamp(playerLane+direction,-1,1)}
function render(){renderer.render(scene,camera)}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,(now-last)/1000||0);last=now;clock+=dt;if(running&&!paused&&!gameOver){const b=bikes[selected],worldSpeed=34+pace*5;distance+=b.speed*pace/3.6*dt;pace=Math.min(1.34,1+distance/1800);spawnTimer-=dt;if(spawnTimer<=0){spawn();spawnTimer=Math.max(.68,1.42-distance/2400)+(Math.random()*.42)}
 lanePosition=THREE.MathUtils.damp(lanePosition,playerLane*2.55,9,dt);bikePivot.position.x=lanePosition;bikePivot.rotation.z=THREE.MathUtils.damp(bikePivot.rotation.z,-(playerLane*2.55-lanePosition)*.05,7,dt);bikePivot.position.y=.045+Math.sin(clock*12)*.025;
 for(const item of scenery){item.z+=worldSpeed*dt*item.speed;item.group.position.z=item.z;if(item.z>24){item.z-=500;item.group.position.z=item.z}}
 for(const mark of roadMarks){mark.position.z+=worldSpeed*dt;if(mark.position.z>18)mark.position.z-=510}
 for(let i=objects.length-1;i>=0;i--){const o=objects[i];o.z+=worldSpeed*dt;o.group.position.z=o.z;if(Math.abs(o.z-2.1)<2.7&&o.lane===playerLane){if(o.type==='token'){marks++;worldGroup.remove(o.group);objects.splice(i,1);continue}else{endRide();break}}if(o.z>18){worldGroup.remove(o.group);objects.splice(i,1)}}
 if(audio&&audio.ctx.state==='running'){audio.osc.frequency.setTargetAtTime(47*b.rpm*(.92+pace*.08),audio.ctx.currentTime,.12);audio.harmonic.frequency.setTargetAtTime(94*b.rpm*(.92+pace*.08),audio.ctx.currentTime,.12)}updateHud()}
 if(currentModel){currentModel.rotation.z=THREE.MathUtils.damp(currentModel.rotation.z,bikePivot.rotation.z,10,dt);currentModel.position.y=.01+Math.sin(clock*12)*.008}camera.position.x=THREE.MathUtils.damp(camera.position.x,lanePosition*.28,2.4,dt);camera.position.y=4.05+Math.sin(clock*6)*.025;camera.lookAt(lanePosition*.12,1.05,-10);render()}
function selectBike(i){if(running)return;selected=i;document.querySelectorAll('.bike-card').forEach((el,j)=>el.classList.toggle('selected',j===i));const b=bikes[i];document.getElementById('rideName').textContent=b.name;document.getElementById('routeName').textContent=b.route;document.getElementById('terrainName').textContent=b.terrain;document.getElementById('routeTip').textContent=b.tip;document.getElementById('stateKicker').textContent=b.type+' · '+b.terrain;buildWorld();loadBike();render()}
bikes.forEach((b,i)=>{const btn=document.createElement('button');btn.className='bike-card'+(i===0?' selected':'');btn.innerHTML=`<span class="bike-type">${b.type}</span><span class="bike-name">${b.name}</span><span class="bike-tag">${b.tag}</span>`;btn.addEventListener('click',()=>selectBike(i));grid.appendChild(btn)});
document.getElementById('startBtn').addEventListener('click',startRide);document.getElementById('leftBtn').addEventListener('click',()=>changeLane(-1));document.getElementById('rightBtn').addEventListener('click',()=>changeLane(1));
window.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight',' ','a','A','d','D','p','P'].includes(event.key))event.preventDefault();if(event.key==='ArrowLeft'||event.key==='a'||event.key==='A')changeLane(-1);if(event.key==='ArrowRight'||event.key==='d'||event.key==='D')changeLane(1);if(event.key==='p'||event.key==='P')pauseRide();if(event.key===' '&&!running)startRide()});
canvas.addEventListener('pointerdown',event=>{if(!running||paused)return;changeLane(event.offsetX<canvas.clientWidth/2?-1:1)});
buildWorld();loadBike();resize();setOverlay(true);updateHud();requestAnimationFrame(animate);

