const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const target = targets.find(item => item.type === 'page');
if (!target) throw new Error('No browser page target');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
let nextId = 0;
const pending = new Map();
const events = [];
ws.addEventListener('message', event => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id); pending.delete(message.id);
    message.error ? reject(new Error(message.error.message)) : resolve(message.result);
  } else if (message.method === 'Runtime.consoleAPICalled') {
    events.push(message.params.args.map(arg => arg.value ?? arg.description).join(' '));
  } else if (message.method === 'Runtime.exceptionThrown') {
    events.push('EXCEPTION ' + message.params.exceptionDetails.text);
  }
});
function call(method, params = {}) {
  const id = ++nextId;
  ws.send(JSON.stringify({ id, method, params }));
  return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
}
await call('Runtime.enable');
await call('Page.enable');
await call('Page.navigate', { url: 'http://127.0.0.1:8765/index.html' });
const evalJS = async expression => (await call('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })).result.value;
let info = null;
for (let i = 0; i < 80 && !info; i++) {
  await new Promise(resolve => setTimeout(resolve, 250));
  info = await evalJS('window.__bikeModelInfo || null');
}
console.log('initial model', JSON.stringify(info));
for (const index of [3, 5, 6, 8, 0]) {
  await evalJS(`document.querySelectorAll('.bike-card')[${index}].click()`);
  let result = null;
  for (let i = 0; i < 80 && (!result || result.asset !== (['classic','roadster','adventure'][index === 5 || index === 6 ? 2 : index === 3 || index === 8 ? 1 : 0])); i++) {
    await new Promise(resolve => setTimeout(resolve, 250));
    result = await evalJS('window.__bikeModelInfo || null');
  }
  console.log('selection', index, JSON.stringify(result));
}
console.log('errors', JSON.stringify(events.filter(item => /EXCEPTION|failed|error/i.test(item))));
ws.close();

